package com.cardcombat;

import java.io.File;import java.util.*;import org.bukkit.*;import org.bukkit.block.Block;import org.bukkit.configuration.*;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.entity.*;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.metadata.FixedMetadataValue;import org.bukkit.potion.*;import org.bukkit.scheduler.BukkitRunnable;import org.bukkit.util.Vector;

public final class CardManager{
 private final CardCombatPlugin p;private final Map<String,CardDefinition>cards=new LinkedHashMap<String,CardDefinition>();
 private final Map<UUID,Integer>mana=new HashMap<UUID,Integer>();private final Map<String,Long>cooldowns=new HashMap<String,Long>();
 private final Map<UUID,Long>combat=new HashMap<UUID,Long>();private final Set<UUID>logged=new HashSet<UUID>();
 private final Map<UUID,String>forms=new HashMap<UUID,String>();private final Map<UUID,Long>formUntil=new HashMap<UUID,Long>();
 private final Map<UUID,PlayState>playanoos=new HashMap<UUID,PlayState>();private final Map<UUID,DomainState>towers=new HashMap<UUID,DomainState>();private final Map<UUID,DomainState>clouds=new HashMap<UUID,DomainState>();
 private final Map<UUID,DomainState>fields=new HashMap<UUID,DomainState>();private final Map<UUID,HomeState>homes=new HashMap<UUID,HomeState>();
 private final Map<UUID,Double>ritualBoost=new HashMap<UUID,Double>();private final Map<UUID,Long>shieldUntil=new HashMap<UUID,Long>();
 private final Map<UUID,List<UUID>>summons=new HashMap<UUID,List<UUID>>();
 private static final String MARK="BCARD:";private static final String OWNER="battlecards_owner";private static final String SUMMON="battlecards_summon";
 public CardManager(CardCombatPlugin p){this.p=p;}
 public void load(){cards.clear();File f=new File(p.getDataFolder(),"cards.yml");YamlConfiguration y=YamlConfiguration.loadConfiguration(f);ConfigurationSection s=y.getConfigurationSection("cards");if(s!=null)for(String id:s.getKeys(false)){ConfigurationSection c=s.getConfigurationSection(id);if(c==null)continue;cards.put(id.toLowerCase(),read(id,c));}installGeneratedCards();p.getLogger().info("Loaded "+cards.size()+" cards.");}
 private CardDefinition read(String id,ConfigurationSection c){return new CardDefinition(id,c.getString("name",id),c.getString("rarity","Common"),c.getString("type","DAMAGE").toUpperCase(),c.getDouble("cooldown",2),c.getDouble("range",18),c.getDouble("power",5),c.getInt("duration",0),c.getInt("mana",5),c.getStringList("description"),c.getBoolean("admin-only",false),c.getString("summon-type",""),c.getString("structure-type",""),c.getDouble("summon-health",20),c.getDouble("summon-damage",4),c.getBoolean("explosion",false),c.getDouble("explosion-power",1),c.getString("element","Arcane"),c.getString("class","General"),c.getBoolean("aoe",false),c.getDouble("aoe-radius",4),c.getDouble("aoe-delay",0),c.getString("form-name",""),c.getDouble("form-mana-drain",0),c.getDouble("domain-damage-multiplier",1));}
 private void installGeneratedCards(){String[]cls=p.classes();for(String cl:cls){String id=cl.toLowerCase();cards.put(id+"_home",gen(id+"_home","&f"+cl+" Home Domain","DOMAIN_HOME",cl,0,0,0,0,10,"Home Domain"));cards.put(id+"_cloud",gen(id+"_cloud","&f"+cl+" Cloud Domain","DOMAIN_CLOUD",cl,0,12,0,0,10,"Cloud Domain"));for(int i=1;i<=3;i++)cards.put(id+"_playanoo_"+i,gen(id+"_playanoo_"+i,"&f"+cl+" Playanoo: Technique "+i,"PLAYANOO_TECH",cl,2+i,18+i*2,9+i*5,0,12+i*2,"Playanoo Technique "+i));}}
 private CardDefinition gen(String id,String name,String type,String cl,double cd,double range,double power,int dur,int mana,String desc){return new CardDefinition(id,name,"Legendary",type,cd,range,power,dur,mana,Arrays.asList("&7"+desc),false,"","",40,8,true,1,cl,cl,false,4,0,"",0,1);}
 public Collection<CardDefinition> all(){return Collections.unmodifiableCollection(cards.values());}public CardDefinition get(String id){return id==null?null:cards.get(id.toLowerCase());}
 public String randomClass(){return p.classes()[new Random().nextInt(p.classes().length)];}
 public ItemStack createItem(String id,int amount){CardDefinition c=get(id);if(c==null)return null;ItemStack i=new ItemStack(Material.PAPER,Math.max(1,Math.min(64,amount)));ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.translateAlternateColorCodes('&',c.name));List<String>l=new ArrayList<String>();l.add(ChatColor.DARK_GRAY+"ID: "+c.id);l.add(ChatColor.GRAY+c.rarity+" • "+c.type);l.add(ChatColor.GRAY+"Mana: "+c.mana+" • Cooldown: "+c.cooldown+"s");for(String d:c.description)l.add(ChatColor.translateAlternateColorCodes('&',d));m.setLore(l);m.setLocalizedName(MARK+c.id);i.setItemMeta(m);return i;}
 public String cardId(ItemStack i){if(i==null||!i.hasItemMeta())return null;String x=i.getItemMeta().getLocalizedName();if(x!=null&&x.startsWith(MARK))return x.substring(MARK.length());if(i.getType()!=Material.PAPER||!i.getItemMeta().hasLore())return null;for(String l:i.getItemMeta().getLore())if(ChatColor.stripColor(l).startsWith("ID: "))return ChatColor.stripColor(l).substring(4).trim().toLowerCase();return null;}
 public void refreshHotbar(Player p){String cl=this.p.profiles().getClass(p);if(cl==null||cl.isEmpty())return;for(int i=0;i<9;i++)p.getInventory().setItem(i,null);int slot=0;for(CardDefinition c:cards.values()){if(slot>=9)break;if(!c.cardClass.equalsIgnoreCase(cl)||c.type.startsWith("DOMAIN_")||c.type.startsWith("PLAYANOO")||c.type.equals("FORM"))continue;if(this.p.isStaff(p)||this.p.economy().owns(p,c.id))p.getInventory().setItem(slot++,createItem(c.id,1));}if(slot<9){for(CardDefinition c:cards.values())if(slot<9&&c.cardClass.equalsIgnoreCase(cl)&&c.type.equals("PLAYANOO")){p.getInventory().setItem(slot++,createItem(c.id,1));break;}}}
 public boolean setHotbarCard(Player p,String id,int slot){if(slot<0||slot>8)return false;CardDefinition c=get(id);if(c==null)return false;if(!canUseCard(p,c))return false;p.getInventory().setItem(slot,createItem(c.id,1));return true;}
 public void removeHotbarCard(Player p,int slot){if(slot>=0&&slot<9)p.getInventory().setItem(slot,null);}
 private boolean canUseCard(Player p,CardDefinition c){if(c.adminOnly&&!this.p.isStaff(p))return false;if(c.cardClass.equalsIgnoreCase(this.p.profiles().getClass(p)))return this.p.isStaff(p)||this.p.economy().owns(p,c.id)||c.type.startsWith("DOMAIN_")||c.type.startsWith("PLAYANOO")||c.type.equals("FORM");return this.p.isStaff(p);}
 public boolean ready(Player p,CardDefinition c){Long t=cooldowns.get(key(p,c));return t==null||t<=System.currentTimeMillis();}public long remaining(Player p,CardDefinition c){Long t=cooldowns.get(key(p,c));return t==null?0:Math.max(0,t-System.currentTimeMillis());}private String key(Player p,CardDefinition c){return p.getUniqueId()+":"+c.id;}
 public int getMana(Player p){Integer n=mana.get(p.getUniqueId());return n==null?this.p.getConfig().getInt("settings.mana.max",100):n;}public void setMana(Player p,int n){mana.put(p.getUniqueId(),Math.max(0,Math.min(this.p.getConfig().getInt("settings.mana.max",100),n)));}public void resetMana(Player p){setMana(p,this.p.getConfig().getInt("settings.mana.max",100));}public void regenMana(){int max=this.p.getConfig().getInt("settings.mana.max",100),add=Math.max(1,this.p.getConfig().getInt("settings.mana.regen-per-second",5));for(Player x:Bukkit.getOnlinePlayers())if(p.isBattleMode(x))setMana(x,getMana(x)+add);}
 public boolean isCombatTagged(Player x){Long t=combat.get(x.getUniqueId());if(t==null)return false;if(t<=System.currentTimeMillis()){combat.remove(x.getUniqueId());return false;}return true;}public long combatRemaining(Player x){Long t=combat.get(x.getUniqueId());return t==null?0:Math.max(0,t-System.currentTimeMillis());}public void tagCombat(Player a,Player b){long t=System.currentTimeMillis()+p.getConfig().getLong("settings.combat-log.seconds",15)*1000L;combat.put(a.getUniqueId(),t);combat.put(b.getUniqueId(),t);}public void clearCombatTag(Player x){combat.remove(x.getUniqueId());}public void markCombatLogged(Player x){logged.add(x.getUniqueId());}public boolean consumeCombatLogged(Player x){return logged.remove(x.getUniqueId());}public void tickCombatTags(){for(UUID u:new HashSet<UUID>(combat.keySet()))if(combat.get(u)<=System.currentTimeMillis())combat.remove(u);}
 public boolean isHomeWorld(Player p){return p!=null&&p.getWorld().getName().equals(homeWorldName(p.getUniqueId()));}public boolean canBuildInHome(Player p){return isHomeWorld(p)&&getPlayerHomeWorld(p)!=null&&p.getWorld().getUID().equals(getPlayerHomeWorld(p).getUID());}
 private String homeWorldName(UUID u){return "bc_home_"+u.toString().replace("-","");}public World getPlayerHomeWorld(Player p){String n=homeWorldName(p.getUniqueId());World w=Bukkit.getWorld(n);if(w==null)w=Bukkit.createWorld(new WorldCreator(n).generator(new VoidGenerator()));return w;}
 public void enterOrExitHome(Player p){if(isCombatTagged(p)){p.sendMessage(ChatColor.RED+"You cannot use the Home Domain while combat tagged.");return;}HomeState h=homes.get(p.getUniqueId());World w=getPlayerHomeWorld(p);if(w==null){p.sendMessage(ChatColor.RED+"Your Home world could not be created.");return;}if(h!=null&&h.open){p.teleport(h.returnLocation);h.open=false;p.sendMessage(ChatColor.YELLOW+"Home Domain closed.");return;}Location ret=p.getLocation().clone();homes.put(p.getUniqueId(),new HomeState(ret,true));ensureHomeShell(p,w);p.teleport(new Location(w,0.5,65,0.5,0,0));p.sendMessage(ChatColor.GREEN+"Home Domain opened. Your builds are saved permanently.");}
 private void ensureHomeShell(Player p,World w){String cl=this.p.profiles().getClass(p);Material glass=classGlass(cl);int r=8,h=7;for(int x=-r;x<=r;x++)for(int z=-r;z<=r;z++)for(int y=60;y<=60+h;y++){boolean shell=Math.abs(x)==r||Math.abs(z)==r||y==60+h;Block b=w.getBlockAt(x,y,z);if(shell&&b.getType()==Material.AIR)setGlass(b,cl);}for(int x=-1;x<=1;x++)for(int y=61;y<=63;y++)w.getBlockAt(x,y,-r).setType(Material.AIR);for(int x=-r+1;x<r;x++)for(int z=-r+1;z<r;z++)for(int y=61;y<60+h;y++){} }
 private Material classGlass(String cl){return Material.STAINED_GLASS;}
 private byte classGlassData(String cl){if(cl==null)return 0;String s=cl.toLowerCase();if(s.equals("shadow")||s.equals("soul"))return 10;if(s.equals("fire")||s.equals("fighting"))return 14;if(s.equals("water"))return 3;if(s.equals("earth"))return 12;if(s.equals("wind")||s.equals("ice"))return 3;if(s.equals("light"))return 4;if(s.equals("dragon"))return 1;if(s.equals("mech"))return 8;if(s.equals("magnitized"))return 7;return 0;}
 private void setGlass(Block b,String cl){b.setType(Material.STAINED_GLASS);b.setData(classGlassData(cl));}
 public void tickClouds(){for(UUID u:new HashSet<UUID>(clouds.keySet())){DomainState d=clouds.get(u);Player p=Bukkit.getPlayer(u);if(p==null||d.expires<System.currentTimeMillis()){if(p!=null&&d.oldFlight)p.setAllowFlight(true);clouds.remove(u);continue;}if(!p.getWorld().equals(d.center.getWorld())||p.getLocation().distanceSquared(d.center)>25){p.setAllowFlight(false);continue;}p.setAllowFlight(true);p.setFlying(true);}}
 public void useCloud(Player p){CardDefinition c=get(this.p.profiles().getClass(p).toLowerCase()+"_cloud");if(c==null)return;if(isCombatTagged(p)){p.sendMessage(ChatColor.RED+"You cannot use the Cloud Domain while combat tagged.");return;}if(!ready(p,c)){p.sendMessage(ChatColor.RED+"Cloud cooldown: "+String.format("%.1f",remaining(p,c)/1000.0)+"s");return;}cooldowns.put(key(p,c),System.currentTimeMillis()+5000);Location center=p.getLocation().clone().add(0,5,0);Material m=classGlass(c.cardClass);for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)setGlass(center.getWorld().getBlockAt(center.getBlockX()+x,center.getBlockY(),center.getBlockZ()+z),c.cardClass);boolean old=p.getAllowFlight();clouds.put(p.getUniqueId(),new DomainState(center,System.currentTimeMillis()+30000,old));p.teleport(center.clone().add(0,1,0));p.setAllowFlight(true);p.setFlying(true);}
 public boolean isHomeLocation(Player p){return isHomeWorld(p);}
 public void tickForms(){for(UUID u:new HashSet<UUID>(forms.keySet())){Player x=Bukkit.getPlayer(u);if(x==null||formUntil.get(u)<=System.currentTimeMillis()){if(x!=null)stopForm(x);continue;}if(x.getTicksLived()%20==0){CardDefinition c=get(forms.get(u));if(c!=null&&c.formManaDrain>0)setMana(x,getMana(x)-(int)Math.ceil(c.formManaDrain));}}}
 public boolean isFormActive(Player p){return forms.containsKey(p.getUniqueId());}public String getActiveForm(Player p){return forms.get(p.getUniqueId());}public void stopForm(Player p){forms.remove(p.getUniqueId());formUntil.remove(p.getUniqueId());for(PotionEffectType t:new PotionEffectType[]{PotionEffectType.INCREASE_DAMAGE,PotionEffectType.SPEED,PotionEffectType.DAMAGE_RESISTANCE})p.removePotionEffect(t);}
 public boolean use(Player p,String id,LivingEntity supplied){CardDefinition c=get(id);if(c==null)return false;if(!canUseCard(p,c)){p.sendMessage(ChatColor.RED+"You cannot use that card.");return false;}if(c.type.equals("DOMAIN_HOME")){enterOrExitHome(p);return true;}if(c.type.equals("DOMAIN_CLOUD")){useCloud(p);return true;}if(c.type.equals("PLAYANOO")){startPlayanoo(p);return true;}if(c.type.equals("PLAYANOO_TECH")){return usePlayanoo(p,c);}if(c.type.equals("FORM"))return useForm(p,c);if(!ready(p,c)){p.sendMessage(ChatColor.RED+"Card cooldown: "+String.format("%.1f",remaining(p,c)/1000.0)+"s");return false;}if(getMana(p)<c.mana){p.sendMessage(ChatColor.RED+"Not enough mana. Need "+(c.mana-getMana(p))+" more.");return false;}LivingEntity target=supplied;if(target==null&&needsTarget(c))target=target(p,c.range);Location center=target==null?p.getLocation().clone().add(p.getLocation().getDirection().multiply(Math.max(2,Math.min(c.range,8)))).add(0,1,0):target.getLocation();if(needsTarget(c)&&target==null){p.sendMessage(ChatColor.RED+"No valid target in range.");return false;}setMana(p,getMana(p)-c.mana);cooldowns.put(key(p,c),System.currentTimeMillis()+(long)(c.cooldown*1000));execute(p,c,target,center);p.sendMessage(ChatColor.GRAY+"Played "+ChatColor.stripColor(ChatColor.translateAlternateColorCodes('&',c.name))+ChatColor.GRAY+".");return true;}
 private boolean needsTarget(CardDefinition c){return !(c.type.startsWith("AREA_")||c.type.equals("HEAL")||c.type.equals("REGEN")||c.type.equals("SPEED")||c.type.equals("HASTE")||c.type.equals("RESIST")||c.type.equals("SHIELD")||c.type.equals("DASH")||c.type.startsWith("DOMAIN_")||c.type.equals("FORM")||c.type.equals("SUMMON")||c.type.equals("PLAYANOO_TECH"));}
 private LivingEntity target(Player p,double range){LivingEntity best=null;double bd=range*range;Vector dir=p.getEyeLocation().getDirection().normalize();for(Entity e:p.getNearbyEntities(range,range,range))if(e instanceof LivingEntity&&e!=p&&!(e instanceof ArmorStand)){LivingEntity l=(LivingEntity)e;Vector to=l.getEyeLocation().toVector().subtract(p.getEyeLocation().toVector());double d=to.length();if(d>range||d<.1)continue;double dot=dir.dot(to.normalize());if(dot<.75)continue;if(d*d<bd){bd=d*d;best=l;}}return best;}
 private void execute(Player p,CardDefinition c,LivingEntity t,Location center){String type=c.type;if(type.equals("DAMAGE")){damage(p,t,c.power);arc(p,t,c);}else if(type.equals("AREA_DAMAGE")){aoe(p,center,c,c.power,false);}else if(type.equals("POISON")){effect(t,PotionEffectType.POISON,c.duration,c.power);damage(p,t,c.power);arc(p,t,c);}else if(type.equals("BLIND")){effect(t,PotionEffectType.BLINDNESS,c.duration,c.power);damage(p,t,c.power*.5);arc(p,t,c);}else if(type.equals("WITHER")){effect(t,PotionEffectType.WITHER,c.duration,c.power);damage(p,t,c.power);arc(p,t,c);}else if(type.equals("WEAKNESS")){effect(t,PotionEffectType.WEAKNESS,c.duration,c.power);damage(p,t,c.power*.4);arc(p,t,c);}else if(type.equals("IGNITE")){if(t!=null)t.setFireTicks(c.duration*20);damage(p,t,c.power);arc(p,t,c);}else if(type.equals("LIGHTNING")){if(t!=null)t.getWorld().strikeLightningEffect(t.getLocation());damage(p,t,c.power);arc(p,t,c);}else if(type.equals("DRAIN")){damage(p,t,c.power);if(t!=null)heal(p,c.power*.5);arc(p,t,c);}else if(type.equals("VAMPIRIC")){damage(p,t,c.power);if(t!=null)heal(p,c.power*.75);arc(p,t,c);}else if(type.equals("KNOCKBACK")){damage(p,t,c.power);knock(t,p.getLocation(),1.2);arc(p,t,c);}else if(type.equals("AREA_KNOCKBACK")){aoe(p,center,c,c.power,true);}else if(type.equals("SLOW")){effect(t,PotionEffectType.SLOW,c.duration,c.power);damage(p,t,c.power*.5);arc(p,t,c);}else if(type.equals("AREA_SLOW")){aoeEffect(p,center,c,PotionEffectType.SLOW);}else if(type.equals("ROOT")||type.equals("FEAR")){effect(t,PotionEffectType.SLOW,c.duration,10);damage(p,t,c.power*.5);arc(p,t,c);}else if(type.equals("AREA_ROOT")){aoeEffect(p,center,c,PotionEffectType.SLOW);}else if(type.equals("AREA_IGNITE")){aoe(p,center,c,c.power,false);}else if(type.equals("HEAL")){heal(p,c.power);burst(p.getLocation(),c.element,false);}else if(type.equals("AREA_HEAL")){heal(p,c.power);for(Entity e:p.getNearbyEntities(c.aoeRadius,c.aoeRadius,c.aoeRadius))if(e instanceof Player)heal((Player)e,c.power*.6);burst(center,c.element,false);}else if(type.equals("REGEN")){p.addPotionEffect(new PotionEffect(PotionEffectType.REGENERATION,c.duration*20,Math.max(0,(int)c.power-1)));}else if(type.equals("SPEED")){p.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,c.duration*20,Math.max(0,(int)c.power-1)));}else if(type.equals("HASTE")){p.addPotionEffect(new PotionEffect(PotionEffectType.FAST_DIGGING,c.duration*20,Math.max(0,(int)c.power-1)));}else if(type.equals("RESIST")){p.addPotionEffect(new PotionEffect(PotionEffectType.DAMAGE_RESISTANCE,c.duration*20,Math.max(0,(int)c.power-1)));}else if(type.equals("SHIELD")){shieldUntil.put(p.getUniqueId(),System.currentTimeMillis()+c.duration*1000L);burst(p.getLocation(),c.element,false);}else if(type.equals("DASH")){Vector v=p.getLocation().getDirection().normalize().multiply(Math.min(2.5,c.power*.3));p.setVelocity(v.setY(.2));}else if(type.equals("SUMMON")){summon(p,c);}else if(type.equals("DOMAIN_TOWER")){tower(p,c);}else if(type.equals("DOMAIN_FIELD")){field(p,c);}else if(type.equals("DOMAIN_ULTIMATE")){aoe(p,center,c,c.power*1.5,true);}else if(type.equals("CHAIN")){if(t!=null){damage(p,t,c.power);for(Entity e:t.getNearbyEntities(5,5,5))if(e instanceof LivingEntity&&e!=p)damage(p,(LivingEntity)e,c.power*.5);arc(p,t,c);}}else if(type.equals("AREA_DAMAGE")){aoe(p,center,c,c.power,false);}if(c.explosion||c.aoe||type.startsWith("AREA_"))explosion(center,c);} 
 private void damage(Player p,LivingEntity t,double n){if(t==null)return;if(t instanceof Player){this.p.cards().tagCombat(p,(Player)t);if(this.p.challenges().isInMatch(p.getUniqueId()))this.p.challenges().markCombat(p,(Player)t);if(((Player)t).isBlocking())n*=.75;}if(isShielded(t))return;t.damage(Math.max(0,n),p);}
 private boolean isShielded(LivingEntity e){return e instanceof Player&&shieldUntil.containsKey(e.getUniqueId())&&shieldUntil.get(e.getUniqueId())>System.currentTimeMillis();}private void heal(Player p,double n){p.setHealth(Math.min(p.getMaxHealth(),p.getHealth()+n));}
 private void effect(LivingEntity e,PotionEffectType t,int sec,double power){if(e==null||t==null)return;e.addPotionEffect(new PotionEffect(t,Math.max(1,sec)*20,Math.max(0,(int)(power/6))));}
 private void knock(LivingEntity e,Location from,double power){if(e==null)return;Vector v=e.getLocation().toVector().subtract(from.toVector()).normalize().multiply(power);v.setY(.45);e.setVelocity(v);}private void aoe(Player p,Location center,CardDefinition c,double damage,boolean knock){for(Entity e:center.getWorld().getNearbyEntities(center,c.aoeRadius,c.aoeRadius,c.aoeRadius))if(e instanceof LivingEntity&&e!=p){LivingEntity l=(LivingEntity)e;damage(p,l,damage);if(knock)knock(l,center,1.2);if(c.type.equals("AREA_IGNITE"))l.setFireTicks(c.duration*20);}burst(center,c.element,true);}
 private void aoeEffect(Player p,Location center,CardDefinition c,PotionEffectType t){for(Entity e:center.getWorld().getNearbyEntities(center,c.aoeRadius,c.aoeRadius,c.aoeRadius))if(e instanceof LivingEntity&&e!=p)effect((LivingEntity)e,t,c.duration,c.power);burst(center,c.element,true);}
 private void explosion(Location l,CardDefinition c){l.getWorld().playSound(l,Sound.EXPLODE,1f,1.0f);if(c.element!=null&&(c.element.toLowerCase().contains("mech")||c.element.toLowerCase().contains("emp")))l.getWorld().spawnParticle(Particle.SPELL_MOB,l,55,0,0,1,1);else burst(l,c.element,true);}
 private void burst(Location l,String element,boolean big){Particle pt=particle(element);int n=big?45:20;l.getWorld().spawnParticle(pt,l,n,big?1.2:.5,big?.7:.3,big?1.2:.5,.05);}
 private Particle particle(String e){String s=e==null?"":e.toLowerCase();if(s.contains("emp")||s.contains("mech"))return Particle.REDSTONE;if(s.contains("fire")||s.contains("dragon"))return Particle.FLAME;if(s.contains("water")||s.contains("ice"))return Particle.SNOWBALL;if(s.contains("earth"))return Particle.BLOCK_CRACK;if(s.contains("wind"))return Particle.CLOUD;if(s.contains("light"))return Particle.END_ROD;if(s.contains("shadow")||s.contains("soul"))return Particle.SPELL_WITCH;if(s.contains("magn"))return Particle.CRIT_MAGIC;return Particle.CRIT_MAGIC;}
 private void arc(Player p,LivingEntity t,CardDefinition c){if(t==null)return;Location a=p.getEyeLocation().clone();Location b=t.getEyeLocation().clone();Vector d=b.toVector().subtract(a.toVector());double len=d.length();if(len<.2)return;Vector forward=d.clone().normalize();Vector side=forward.clone().crossProduct(new Vector(0,1,0));if(side.length()<.1)side=new Vector(1,0,0);side.normalize();int points=Math.max(10,(int)(len/.3));for(int i=0;i<=points;i++){double u=i/(double)points;double y=Math.sin(u*Math.PI)*1.6;double sideOffset=Math.sin(u*Math.PI)*.55;Vector pos=a.toVector().add(d.clone().multiply(u)).add(new Vector(0,y,0)).add(side.clone().multiply(sideOffset));a.getWorld().spawnParticle(particle(c.element),pos.getX(),pos.getY(),pos.getZ(),2,0,0,0,0);}}
 private void summon(Player p,CardDefinition c){List<UUID>list=summons.get(p.getUniqueId());if(list==null){list=new ArrayList<UUID>();summons.put(p.getUniqueId(),list);}list.removeIf(u->Bukkit.getEntity(u)==null);int max=this.p.getConfig().getInt("settings.summons.max-per-player",3);if(list.size()>=max){p.sendMessage(ChatColor.RED+"You already have the maximum number of summons.");return;}EntityType type;try{type=EntityType.valueOf(c.summonType.toUpperCase());}catch(Exception e){type=EntityType.ZOMBIE;}Entity e=p.getWorld().spawnEntity(p.getLocation().add(p.getLocation().getDirection().multiply(2)),type);if(!(e instanceof LivingEntity)){e.remove();return;}LivingEntity l=(LivingEntity)e;l.setMaxHealth(Math.max(1,c.summonHealth));l.setHealth(l.getMaxHealth());l.setCustomName(ChatColor.translateAlternateColorCodes('&',c.name));l.setMetadata(SUMMON,new FixedMetadataValue(this.p,true));l.setMetadata(OWNER,new FixedMetadataValue(this.p,p.getUniqueId().toString()));list.add(l.getUniqueId());}
 public void tickSummons(){for(Map.Entry<UUID,List<UUID>>en:new HashMap<UUID,List<UUID>>(summons).entrySet()){Player owner=Bukkit.getPlayer(en.getKey());if(owner==null)continue;for(UUID id:new ArrayList<UUID>(en.getValue())){Entity e=Bukkit.getEntity(id);if(!(e instanceof LivingEntity)){en.getValue().remove(id);continue;}LivingEntity l=(LivingEntity)e;LivingEntity target=nearestEnemy(l,owner,12);if(target!=null&&l.getTicksLived()%20==0){target.damage(3,owner);burst(target.getLocation(),owner.getName(),false);}}}}
 private LivingEntity nearestEnemy(LivingEntity a,Player owner,double r){LivingEntity best=null;double bd=r*r;for(Entity e:a.getNearbyEntities(r,r,r))if(e instanceof LivingEntity&&e!=a&&e!=owner){double d=e.getLocation().distanceSquared(a.getLocation());if(d<bd){bd=d;best=(LivingEntity)e;}}return best;}
 public boolean isSummon(Entity e){return e!=null&&e.hasMetadata(SUMMON);}public UUID summonOwner(Entity e){if(!isSummon(e))return null;try{return UUID.fromString(e.getMetadata(OWNER).get(0).asString());}catch(Exception ex){return null;}}public double summonDamage(Entity e){return 3;}
 public void onSummonDeath(Entity e){UUID o=summonOwner(e);if(o!=null&&summons.containsKey(o))summons.get(o).remove(e.getUniqueId());}
 public void cleanupSummons(Player p){List<UUID>x=summons.remove(p.getUniqueId());if(x!=null)for(UUID u:x){Entity e=Bukkit.getEntity(u);if(e!=null)e.remove();}}
 private Object pget(){return p;}
 public boolean useForm(Player p,CardDefinition c){if(!ready(p,c)||getMana(p)<c.mana)return false;setMana(p,getMana(p)-c.mana);cooldowns.put(key(p,c),System.currentTimeMillis()+(long)(c.cooldown*1000));stopForm(p);forms.put(p.getUniqueId(),c.id);formUntil.put(p.getUniqueId(),System.currentTimeMillis()+Math.max(1,c.duration)*1000L);p.addPotionEffect(new PotionEffect(PotionEffectType.INCREASE_DAMAGE,Math.max(1,c.duration)*20,1));p.addPotionEffect(new PotionEffect(PotionEffectType.DAMAGE_RESISTANCE,Math.max(1,c.duration)*20,0));return true;}
 private boolean usePlayanoo(Player p,CardDefinition c){if(!playanoos.containsKey(p.getUniqueId())){if(c.type.equals("PLAYANOO_TECH")){p.sendMessage(ChatColor.RED+"Activate your Playanoo first.");return false;}return false;}if(!ready(p,c)||getMana(p)<c.mana)return false;setMana(p,getMana(p)-c.mana);cooldowns.put(key(p,c),System.currentTimeMillis()+(long)(c.cooldown*1000));LivingEntity t=target(p,c.range);Location center=t==null?p.getLocation().clone().add(p.getLocation().getDirection().multiply(6)):t.getLocation();if(t!=null)damage(p,t,c.power);aoe(p,center,c,c.power*.75,true);arc(p,t,c);return true;}
 public void startPlayanoo(Player p){if(playanoos.containsKey(p.getUniqueId()))return;String cl=this.p.profiles().getClass(p);if(cl.isEmpty())return;ItemStack[]inv=p.getInventory().getContents().clone();ItemStack off=p.getInventory().getItemInOffHand();p.getInventory().clear();for(int i=1;i<=3;i++)p.getInventory().setItem(i-1,createItem(cl.toLowerCase()+"_playanoo_"+i,1));playanoos.put(p.getUniqueId(),new PlayState(inv,off,System.currentTimeMillis()+30000));p.sendMessage(ChatColor.LIGHT_PURPLE+"Playanoo activated for 30 seconds.");}
 public void tickPlayanoos(){for(UUID u:new HashSet<UUID>(playanoos.keySet())){Player p=Bukkit.getPlayer(u);PlayState s=playanoos.get(u);if(p==null||s.until<=System.currentTimeMillis()){if(p!=null)stopPlayanoo(p);}}}
 public void stopPlayanoo(Player p){PlayState s=playanoos.remove(p.getUniqueId());if(s==null)return;p.getInventory().clear();p.getInventory().setContents(s.contents);p.getInventory().setItemInOffHand(s.off);p.sendMessage(ChatColor.YELLOW+"Playanoo ended. Your original cards were restored.");}
 public void tower(Player p,CardDefinition c){Location center=p.getLocation().getBlock().getLocation().add(.5,0,.5);Material m=classGlass(c.cardClass);for(int y=0;y<8;y++)for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)if(Math.abs(x)==2||Math.abs(z)==2||y==7)setGlass(center.getWorld().getBlockAt(center.getBlockX()+x,center.getBlockY()+y,center.getBlockZ()+z),c.cardClass);boolean old=p.getAllowFlight();towers.put(p.getUniqueId(),new DomainState(center,System.currentTimeMillis()+Math.max(5,c.duration)*1000L,old));}
 public void tickDomainTowers(){for(UUID u:new HashSet<UUID>(towers.keySet())){DomainState d=towers.get(u);Player p=Bukkit.getPlayer(u);if(p==null||d.expires<=System.currentTimeMillis()){if(p!=null)p.setAllowFlight(d.oldFlight);towers.remove(u);continue;}if(p.getWorld().equals(d.center.getWorld())&&p.getLocation().distanceSquared(d.center)<=100){p.setAllowFlight(true);}else if(!d.oldFlight)p.setAllowFlight(false);}}
 public void field(Player p,CardDefinition c){fields.put(p.getUniqueId(),new DomainState(p.getLocation().clone(),System.currentTimeMillis()+Math.max(5,c.duration)*1000L,false));}
 public void tickFields(){for(UUID u:new HashSet<UUID>(fields.keySet()))if(fields.get(u).expires<=System.currentTimeMillis())fields.remove(u);}
 public boolean inDomainField(Player p){DomainState d=fields.get(p.getUniqueId());return d!=null&&d.expires>System.currentTimeMillis()&&p.getWorld().equals(d.center.getWorld())&&p.getLocation().distanceSquared(d.center)<=d.center.getY()*0+d.center.getX()*0+100;}
 public boolean shielded(Player p){Long t=shieldUntil.get(p.getUniqueId());return t!=null&&t>System.currentTimeMillis();}
 public void mageArmorParticles(Player p){if(p.getTicksLived()%3==0)p.getWorld().spawnParticle(Particle.SPELL_WITCH,p.getLocation().add(0,1,0),6,.4,.7,.4,.03);}
 public void showDamage(Location l,double amount){l.getWorld().spawnParticle(Particle.CRIT,l,8,.3,.4,.3,.03);}
 public void removePlayer(Player p){mana.remove(p.getUniqueId());cooldowns.keySet().removeIf(k->k.startsWith(p.getUniqueId().toString()+":"));stopForm(p);stopPlayanoo(p);cleanupSummons(p);clouds.remove(p.getUniqueId());towers.remove(p.getUniqueId());fields.remove(p.getUniqueId());homes.remove(p.getUniqueId());}
 public boolean setRitualBoost(Player p,String card,double amount){if(ritualBoost.containsKey(p.getUniqueId()))return false;ritualBoost.put(p.getUniqueId(),amount);return true;}public boolean hasRitualBoost(Player p){return ritualBoost.containsKey(p.getUniqueId());}public String getRitualBoostCard(Player p){return "ritual";}public double getRitualBoostAmount(Player p){Double d=ritualBoost.get(p.getUniqueId());return d==null?0:d;}public void clearRitualBoost(Player p){ritualBoost.remove(p.getUniqueId());}
 public boolean createBasicCard(String id,String name,String type,double power){if(get(id)!=null)return false;File f=new File(p.getDataFolder(),"cards.yml");YamlConfiguration y=YamlConfiguration.loadConfiguration(f);String b="cards."+id;y.set(b+".name",name);y.set(b+".rarity","Common");y.set(b+".cooldown",2);y.set(b+".range",18);y.set(b+".type",type);y.set(b+".power",power);y.set(b+".duration",0);y.set(b+".mana",5);y.set(b+".element","Arcane");y.set(b+".class","General");try{y.save(f);load();return true;}catch(Exception e){return false;}}
 public boolean deleteCard(String id){if(get(id)==null)return false;File f=new File(p.getDataFolder(),"cards.yml");YamlConfiguration y=YamlConfiguration.loadConfiguration(f);y.set("cards."+id.toLowerCase(),null);try{y.save(f);load();return true;}catch(Exception e){return false;}}
 public Inventory createCardMenu(Player player){String cls=p.profiles().getClass(player);if(cls==null||cls.isEmpty())return createClassMenu();Inventory inv=Bukkit.createInventory(null,54,ChatColor.DARK_GRAY+"BattleCards • "+cls);int slot=0;for(CardDefinition c:cards.values()){if(!c.cardClass.equalsIgnoreCase(cls))continue;if(slot>=45)break;ItemStack i=createItem(c.id,1);if(i==null)continue;ItemMeta m=i.getItemMeta();List<String>l=m.hasLore()?new ArrayList<String>(m.getLore()):new ArrayList<String>();boolean locked=!(p.isStaff(player)||p.economy().owns(player,c.id))&&!c.type.startsWith("DOMAIN_")&&!c.type.startsWith("PLAYANOO")&&!c.type.equals("FORM");if(locked){m.setDisplayName(ChatColor.RED+"LOCKED • "+ChatColor.stripColor(m.getDisplayName()));l.add(ChatColor.RED+"Unlock this card in /shop");}else l.add(ChatColor.GREEN+"Click to add to your first empty hotbar slot");m.setLore(l);i.setItemMeta(m);inv.setItem(slot++,i);}inv.setItem(49,menuItem(Material.NETHER_STAR,ChatColor.GOLD+"Class: "+cls));return inv;}
public Inventory createClassMenu(){Inventory inv=Bukkit.createInventory(null,27,ChatColor.DARK_GRAY+"BattleCards • Choose Class");int slot=0;for(String c:p.classes())inv.setItem(slot++,menuItem(Material.NETHER_STAR,ChatColor.translateAlternateColorCodes('&',classNameColor(c)+c)));return inv;}
private String classNameColor(String c){String s=c.toLowerCase();if(s.equals("fire")||s.equals("fighting"))return "&c";if(s.equals("water")||s.equals("ice")||s.equals("wind"))return "&b";if(s.equals("earth"))return "&6";if(s.equals("light"))return "&e";if(s.equals("dragon"))return "&6";if(s.equals("mech"))return "&7";if(s.equals("magnitized"))return "&8";return "&5";}
private ItemStack menuItem(Material m,String name){ItemStack i=new ItemStack(m);ItemMeta meta=i.getItemMeta();meta.setDisplayName(name);i.setItemMeta(meta);return i;}
public void cleanupStructures(){for(UUID u:new HashSet<UUID>(towers.keySet())){Player p=Bukkit.getPlayer(u);if(p!=null)p.setAllowFlight(towers.get(u).oldFlight);}towers.clear();clouds.clear();fields.clear();}
 public void run(){tickCombatTags();tickClouds();tickDomainTowers();tickFields();tickForms();tickPlayanoos();tickSummons();}
 public boolean isHomeWorld(World w){return w!=null&&w.getName().startsWith("bc_home_");}
 private static final class PlayState{final ItemStack[]contents;final ItemStack off;final long until;PlayState(ItemStack[]c,ItemStack o,long u){contents=c;off=o;until=u;}}
 private static final class DomainState{final Location center;final long expires;final boolean oldFlight;DomainState(Location l,long e,boolean f){center=l;expires=e;oldFlight=f;}}
 private static final class HomeState{final Location returnLocation;boolean open;HomeState(Location l,boolean o){returnLocation=l;open=o;}}
 public static final class VoidGenerator extends org.bukkit.generator.ChunkGenerator{public ChunkData generateChunkData(World world,Random random,int x,int z,org.bukkit.generator.ChunkGenerator.BiomeGrid biome){return createChunkData(world);}}
}
